package com.edubridge.voice;

import com.edubridge.auth.UserRepository; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/voice") public class LiveKitController { private final UserRepository users; private final String url,key,secret; public LiveKitController(UserRepository u,@Value("${livekit.url:}") String url,@Value("${livekit.api-key:}") String key,@Value("${livekit.api-secret:}") String secret){users=u;this.url=url;this.key=key;this.secret=secret;} public record TokenRequest(String room){} public record TokenResponse(String url,String token){} @PostMapping("/token") public TokenResponse token(@RequestBody TokenRequest r,java.security.Principal p){if(url.isBlank()||key.isBlank()||secret.length()<32)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"LiveKit is not configured");String room=r.room()==null?"":r.room().trim();if(!room.matches("[A-Za-z0-9_-]{2,80}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid room");var u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();Instant now=Instant.now();SecretKey sk=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));String jwt=Jwts.builder().header().add("typ","JWT").and().issuer(key).subject(u.getId().toString()).claim("name",u.getDisplayName()).claim("video",Map.of("roomJoin",true,"room",room,"canPublish",true,"canSubscribe",true,"canPublishData",true)).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(3600))).signWith(sk).compact();return new TokenResponse(url,jwt);} }
